PRAGMA defer_foreign_keys=ON;
CREATE TABLE users(id INTEGER PRIMARY KEY,name TEXT NOT NULL,username TEXT UNIQUE NOT NULL,password TEXT NOT NULL,role TEXT NOT NULL,line INTEGER,stage TEXT,active INTEGER DEFAULT 1);
CREATE TABLE sessions(token TEXT PRIMARY KEY,user_id INTEGER NOT NULL REFERENCES users(id),expires TEXT NOT NULL);
CREATE TABLE products(id INTEGER PRIMARY KEY,code TEXT UNIQUE NOT NULL,name TEXT NOT NULL,image TEXT DEFAULT '',rate INTEGER NOT NULL DEFAULT 35000,notes TEXT DEFAULT '');
CREATE TABLE sizes(name TEXT PRIMARY KEY);
CREATE TABLE colors(name TEXT PRIMARY KEY,hex TEXT NOT NULL);
CREATE TABLE orders(id INTEGER PRIMARY KEY,customer TEXT NOT NULL,product_id INTEGER NOT NULL REFERENCES products(id),received TEXT NOT NULL,deadline TEXT NOT NULL,priority TEXT NOT NULL,owner_id INTEGER NOT NULL REFERENCES users(id),notes TEXT DEFAULT '',completed_at TEXT);
CREATE TABLE variants(id INTEGER PRIMARY KEY,order_id INTEGER NOT NULL REFERENCES orders(id),color TEXT NOT NULL REFERENCES colors(name),size TEXT NOT NULL REFERENCES sizes(name),qty INTEGER NOT NULL CHECK(qty>0),line INTEGER NOT NULL CHECK(line BETWEEN 1 AND 5),npl INTEGER DEFAULT 0,pattern INTEGER DEFAULT 0,cut INTEGER DEFAULT 0,sew INTEGER DEFAULT 0,qc_checked INTEGER DEFAULT 0,qc_pass INTEGER DEFAULT 0,qc_fail INTEGER DEFAULT 0,repair INTEGER DEFAULT 0,recheck_checked INTEGER DEFAULT 0,recheck_pass INTEGER DEFAULT 0,recheck_fail INTEGER DEFAULT 0,pack INTEGER DEFAULT 0,ship INTEGER DEFAULT 0,UNIQUE(order_id,color,size));
CREATE TABLE stage_meta(order_id INTEGER REFERENCES orders(id),stage TEXT NOT NULL,assignee_id INTEGER REFERENCES users(id),received_at TEXT,started_at TEXT,completed_at TEXT,status TEXT DEFAULT 'Chưa bắt đầu',received_qty INTEGER DEFAULT 0,notes TEXT DEFAULT '',PRIMARY KEY(order_id,stage));
CREATE TABLE entries(id INTEGER PRIMARY KEY,variant_id INTEGER NOT NULL REFERENCES variants(id),order_id INTEGER NOT NULL REFERENCES orders(id),product_id INTEGER NOT NULL REFERENCES products(id),employee_id INTEGER NOT NULL REFERENCES users(id),line INTEGER NOT NULL,stage TEXT NOT NULL,date TEXT NOT NULL,qty INTEGER NOT NULL CHECK(qty>0),rate INTEGER NOT NULL CHECK(rate>=0),amount INTEGER NOT NULL,passed INTEGER DEFAULT 0,failed INTEGER DEFAULT 0,defect TEXT DEFAULT '',image TEXT DEFAULT '',parcels INTEGER DEFAULT 0,notes TEXT DEFAULT '',created_by INTEGER NOT NULL REFERENCES users(id),created_at TEXT NOT NULL,updated_at TEXT);
CREATE TABLE payroll_locks(month TEXT PRIMARY KEY,locked_by INTEGER NOT NULL REFERENCES users(id),locked_at TEXT NOT NULL);
CREATE TABLE logs(id INTEGER PRIMARY KEY,user_id INTEGER REFERENCES users(id),action TEXT NOT NULL,entity TEXT NOT NULL,detail TEXT NOT NULL,created_at TEXT NOT NULL);
CREATE INDEX idx_entries_date_employee ON entries(date,employee_id);
CREATE INDEX idx_entries_order_stage ON entries(order_id,stage);
CREATE INDEX idx_variants_order ON variants(order_id);
CREATE TRIGGER logs_no_delete BEFORE DELETE ON logs BEGIN SELECT RAISE(ABORT,'Không được xóa nhật ký'); END;
CREATE TRIGGER logs_no_update BEFORE UPDATE ON logs BEGIN SELECT RAISE(ABORT,'Không được sửa nhật ký'); END;
CREATE TABLE app_revision(id INTEGER PRIMARY KEY CHECK(id=1),version INTEGER NOT NULL);
